import { InputFile } from 'sdk';
import { db } from 'sdk';
import { eq } from 'sdk/db';
import { userSettings } from '../schema.js';

let cachedFileId = null;

// Base64 lookup table for zero-dependency decoding in V8 isolate
const b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const b64lookup = new Uint8Array(256);
for (let i = 0; i < b64chars.length; i++) b64lookup[b64chars.charCodeAt(i)] = i;

export function decodeBase64(base64) {
  let bufferLength = Math.floor(base64.length * 0.75);
  const len = base64.length;
  if (base64[len - 1] === '=') {
    bufferLength--;
    if (base64[len - 2] === '=') bufferLength--;
  }
  const bytes = new Uint8Array(bufferLength);
  let p = 0;
  for (let i = 0; i < len; i += 4) {
    const encoded1 = b64lookup[base64.charCodeAt(i)];
    const encoded2 = b64lookup[base64.charCodeAt(i + 1)];
    const encoded3 = b64lookup[base64.charCodeAt(i + 2)];
    const encoded4 = b64lookup[base64.charCodeAt(i + 3)];
    bytes[p++] = (encoded1 << 2) | (encoded2 >> 4);
    if (p < bufferLength) bytes[p++] = ((encoded2 & 15) << 4) | (encoded3 >> 2);
    if (p < bufferLength) bytes[p++] = ((encoded3 & 3) << 6) | (encoded4 & 63);
  }
  return bytes;
}

const LOGO_BASE64 = '';

export function getLogoInputFile() {
  const bytes = decodeBase64(LOGO_BASE64);
  return new InputFile(bytes, 'remnoten-logo.png', { type: 'image/png' });
}

export async function getWelcomePhoto() {
  if (cachedFileId) return cachedFileId;

  // Check persistent system settings (chatId 0)
  try {
    const row = await db.select().from(userSettings).where(eq(userSettings.chatId, 0)).get();
    if (row?.state) {
      const data = JSON.parse(row.state);
      if (data?.welcomeFileId) {
        cachedFileId = data.welcomeFileId;
        return cachedFileId;
      }
    }
  } catch {
    // Ignore DB read failure
  }

  // Fallback to fresh InputFile upload
  return getLogoInputFile();
}

export async function rememberWelcomePhotoFileId(fileId) {
  if (!fileId) return;
  cachedFileId = fileId;
  try {
    const stateStr = JSON.stringify({ welcomeFileId: fileId });
    await db.insert(userSettings).values({
      chatId: 0,
      state: stateStr,
    }).onConflictDoUpdate({
      target: userSettings.chatId,
      set: { state: stateStr },
    }).run();
  } catch {
    // Ignore DB save failure
  }
}
